import * as SecureStoreNamespace from 'expo-secure-store';

type SecureStoreFn = (...args: any[]) => any;

// expo-secure-store has had different export shapes across versions/builds.
// The reported runtime error:
//   default.getValueWithKeyAsync is not a function
// suggests that the bundled module does NOT expose that legacy method on `default`.
// This shim avoids relying on `default.getValueWithKeyAsync` existing.

const SecureStoreAny = SecureStoreNamespace as any;
const defaultExport: any = SecureStoreAny?.default;

const getNamed = (name: string): SecureStoreFn | undefined => {
  const v = SecureStoreAny?.[name];
  return typeof v === 'function' ? v : undefined;
};

const getFromDefault = (name: string): SecureStoreFn | undefined => {
  const v = defaultExport?.[name];
  return typeof v === 'function' ? v : undefined;
};

// Prefer modern API first.
const getItemAsyncFn: undefined | ((key: string) => Promise<string | null>) =
  (getNamed('getItemAsync') ?? getFromDefault('getItemAsync')
  // Fallback to legacy API *but only if it exists*.
  ?? getNamed('getValueWithKeyAsync')
  ?? getFromDefault('getValueWithKeyAsync')) as any;

const setItemAsyncFn: undefined | ((key: string, value: string) => Promise<void>) =
  (getNamed('setItemAsync') ?? getFromDefault('setItemAsync')
  ?? getNamed('setValueWithKeyAsync')
  ?? getFromDefault('setValueWithKeyAsync')) as any;

const deleteItemAsyncFn: undefined | ((key: string) => Promise<void>) =
  (getNamed('deleteItemAsync') ?? getFromDefault('deleteItemAsync')
  ?? getNamed('deleteKeyAsync')
  ?? getFromDefault('deleteKeyAsync')) as any;

// Emit a one-time diagnostic so we know which functions were detected.
// eslint-disable-next-line no-console
console.log('[secureStore shim] export shape', {
  hasGetItemAsync: Boolean(getNamed('getItemAsync') ?? getFromDefault('getItemAsync')),
  hasGetValueWithKeyAsync: Boolean(getNamed('getValueWithKeyAsync') ?? getFromDefault('getValueWithKeyAsync')),
  hasSetItemAsync: Boolean(getNamed('setItemAsync') ?? getFromDefault('setItemAsync')),
  hasSetValueWithKeyAsync: Boolean(getNamed('setValueWithKeyAsync') ?? getFromDefault('setValueWithKeyAsync')),
  hasDeleteItemAsync: Boolean(getNamed('deleteItemAsync') ?? getFromDefault('deleteItemAsync')),
  hasDeleteKeyAsync: Boolean(getNamed('deleteKeyAsync') ?? getFromDefault('deleteKeyAsync'))
});

if (!getItemAsyncFn) {
  // eslint-disable-next-line no-console
  console.warn(
    '[secureStore shim] Could not find getItemAsync/getValueWithKeyAsync in expo-secure-store. '
      + 'Stored session handling may fail.'
  );
}

export const secureStore = {
  async setItemAsync(key: string, value: string) {
    if (!setItemAsyncFn) {
      throw new Error('expo-secure-store: setItemAsync not available');
    }
    return setItemAsyncFn(key, value);
  },

  async getItemAsync(key: string) {
    if (!getItemAsyncFn) {
      throw new Error('expo-secure-store: getItemAsync not available');
    }
    return getItemAsyncFn(key);
  },

  async deleteItemAsync(key: string) {
    if (!deleteItemAsyncFn) {
      throw new Error('expo-secure-store: deleteItemAsync not available');
    }
    return deleteItemAsyncFn(key);
  }
};
